// Helper: 会データに plan の中身を合成して使いやすくする
// 冪等化済み：既にenrich済みのsessionが渡されてもエラーにならない
function enrichSession(s) {
  if (!s) return s;
  // 既にenrich済み（plan が文字列ではなくオブジェクト、brandも持っている）の場合はそのまま返す
  if (s.brand && typeof s.plan === 'object') return s;
  const planKey = typeof s.plan === 'string' ? s.plan : null;
  const plan = planKey ? PLAN_DEFS[planKey] : null;
  if (!plan) return s; // 想定外のデータでもクラッシュしない
  const brand = BRAND[plan.brand];
  return {
    ...s,
    brand,
    plan,
    type: plan.label,
    price: s.customPrice ?? plan.price ?? 0,
    capacity: plan.capacity,
    title: s.customTitle || plan.label,
    isOnline: plan.mode === 'online',
    isOffline: plan.mode === 'offline',
    venue: plan.venue || s.platform,
    isClosed: plan.brand === 'closed',
  };
}

const fmtYen = (n) => '¥' + n.toLocaleString('ja-JP');
// "2026-05-15" → "5/15"  /  曜日付き: fmtMD(d, '金') → "5/15（金）"
const fmtMD = (dateStr, day) => {
  if (!dateStr || typeof dateStr !== 'string') return '';
  const m = Number(dateStr.slice(5, 7));
  const d = Number(dateStr.slice(8, 10));
  if (isNaN(m) || isNaN(d)) return dateStr;
  return day ? `${m}/${d}（${day}）` : `${m}/${d}`;
};

// =====================================================================
// トースト通知
// =====================================================================
const ToastContext = createContext(null);
const useToast = () => useContext(ToastContext);

function ToastProvider({ children }) {
  const [toasts, setToasts] = useState([]);
  const idRef = useRef(0);

  const push = (message, type = 'success') => {
    const id = ++idRef.current;
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 3500);
  };

  return (
    <ToastContext.Provider value={{ push }}>
      {children}
      <div style={{
        position: 'fixed', bottom: 24, right: 24, zIndex: 1000,
        display: 'flex', flexDirection: 'column', gap: 8,
        pointerEvents: 'none',
      }}>
        {toasts.map(t => {
          const colorMap = {
            success: { bg: '#e6f3eb', bd: '#3a8c5b', tx: '#2d6e47' },
            info: { bg: '#e6f1f9', bd: '#3a8dc4', tx: '#2c6f9b' },
            warn: { bg: '#fef7e8', bd: '#c9962a', tx: '#a47b1f' },
            error: { bg: '#fce8e0', bd: '#d97757', tx: '#a85a3f' },
          };
          const c = colorMap[t.type] || colorMap.success;
          const Icon = t.type === 'success' ? CheckCircle2 : t.type === 'error' ? XCircle : t.type === 'warn' ? AlertTriangle : Bell;
          return (
            <div key={t.id} style={{
              minWidth: 280, maxWidth: 380,
              padding: '12px 16px',
              background: c.bg,
              border: `1.5px solid ${c.bd}`,
              borderRadius: 10,
              boxShadow: '0 8px 24px rgba(0,0,0,0.1)',
              color: c.tx,
              fontSize: 13, fontWeight: 600,
              display: 'flex', alignItems: 'center', gap: 10,
              pointerEvents: 'auto',
              animation: 'toastIn 0.3s ease-out',
            }}>
              <Icon size={16} strokeWidth={2.5} />
              <span style={{ flex: 1 }}>{t.message}</span>
            </div>
          );
        })}
      </div>
    </ToastContext.Provider>
  );
}

// =====================================================================
// 認証（Firebase Auth）— ログイン状態と運営者判定を全画面に供給
//   user: 現在のユーザー（運営者=メール/PW, 参加者=Google）
//   isAdmin: カスタムクレーム admin:true を持つ運営者か
// =====================================================================
const AuthContext = createContext({ user: null, isAdmin: false, loading: true });
const useAuth = () => useContext(AuthContext);

function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [isAdmin, setIsAdmin] = useState(false);
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    // 起動時に復元（リロードしてもログイン状態が保たれる）
    const unsub = onAuthChange(async (u) => {
      setUser(u);
      if (u) {
        try {
          const t = await u.getIdTokenResult();
          setIsAdmin(t.claims.admin === true);
        } catch {
          setIsAdmin(false);
        }
      } else {
        setIsAdmin(false);
      }
      setLoading(false);
    });
    return () => unsub();
  }, []);
  return <AuthContext.Provider value={{ user, isAdmin, loading }}>{children}</AuthContext.Provider>;
}

// =====================================================================
// 顧客データ（Firestore）— ToastProvider と同じ Context 流儀で全画面に供給
// CUSTOMERS は読み取り専用のため state ではなく Context で配る（prop-drilling 回避）
// =====================================================================
const CustomersContext = createContext([]);
const useCustomers = () => useContext(CustomersContext);

function CustomersProvider({ children }) {
  const [customers, setCustomers] = useState([]);
  const toast = useToast();
  useEffect(() => {
    const unsub = subscribeCustomers(
      rows => setCustomers(rows),
      () => toast.push('顧客データの読み込みに失敗しました', 'error'),
    );
    return () => unsub();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps
  return <CustomersContext.Provider value={customers}>{children}</CustomersContext.Provider>;
}

// =====================================================================
// 参加者プロフィール（Cloud Functions 経由）— Google ログイン後に解決
//   profile: 自分の安全プロフィール（最小開示） / needHandle: 初回ハンドル入力が必要
//   linkHandle(handle): 初回リンク / loading: 解決中
//   ※運営者(isAdmin)や未ログイン時は解決しない
// =====================================================================
const ParticipantContext = createContext({ profile: null, needHandle: false, loading: false, linkHandle: async () => {} });
const useParticipant = () => useContext(ParticipantContext);

function ParticipantProvider({ children }) {
  const { user, isAdmin } = useAuth();
  const toast = useToast();
  const [profile, setProfile] = useState(null);
  const [needHandle, setNeedHandle] = useState(false);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    let active = true;
    if (!user || isAdmin) { setProfile(null); setNeedHandle(false); setLoading(false); return; }
    setLoading(true);
    claimProfile({})
      .then(res => {
        if (!active) return;
        if (res.linked) { setProfile(res.profile); setNeedHandle(false); }
        else { setProfile(null); setNeedHandle(true); }
      })
      .catch(() => { if (active) toast.push('プロフィールの取得に失敗しました', 'error'); })
      .finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, [user, isAdmin]); // eslint-disable-line react-hooks/exhaustive-deps

  const linkHandle = async (handle) => {
    const res = await claimProfile({ handle });
    if (res.linked) { setProfile(res.profile); setNeedHandle(false); }
    return res;
  };

  return (
    <ParticipantContext.Provider value={{ profile, needHandle, loading, linkHandle }}>
      {children}
    </ParticipantContext.Provider>
  );
}

