// ============ 日程調整（一覧）============
const POLL_TODAY = '2026-05-03'; // デモ用の今日（カレンダー等と統一）

// 回答進捗: 回答済み人数 / 対象人数（招待制は招待数、公開は全顧客数）
function pollProgress(poll, pollResponses, totalCustomers) {
  const responded = pollResponses.filter(r => r.pollId === poll.id).length;
  const target = poll.invitedCustomerIds ? poll.invitedCustomerIds.length : totalCustomers;
  return { responded, target, ratio: target ? Math.min(1, responded / target) : 0 };
}

// 推奨期限までの残日数（負なら超過）
function daysUntil(dateStr, fromStr = POLL_TODAY) {
  if (!dateStr) return null;
  const a = new Date(fromStr), b = new Date(dateStr);
  if (isNaN(a.getTime()) || isNaN(b.getTime())) return null;
  return Math.round((b - a) / 86400000);
}

function PollCard({ poll, pollResponses, onClick }) {
  const customers = useCustomers();
  const brand = BRAND[poll.brand];
  const { responded, target, ratio } = pollProgress(poll, pollResponses, customers.length);
  const left = daysUntil(poll.deadline);
  const confirmed = poll.status === 'confirmed';
  const confDate = confirmed && poll.confirmedIndex != null ? poll.candidateDates[poll.confirmedIndex] : null;

  const deadlineLabel = left == null ? '—'
    : left > 0 ? `推奨期限まで残${left}日`
    : left === 0 ? '本日が推奨期限'
    : `推奨期限を${Math.abs(left)}日超過`;

  return (
    <button onClick={onClick} style={{
      textAlign: 'left', width: '100%', cursor: 'pointer',
      background: '#fff', border: '1px solid #e8e5dd', borderRadius: 14,
      padding: 18, fontFamily: 'inherit', display: 'block',
      transition: 'box-shadow 0.2s, transform 0.2s',
    }}
      onMouseEnter={(e) => { e.currentTarget.style.boxShadow = '0 4px 16px rgba(0,0,0,0.06)'; e.currentTarget.style.transform = 'translateY(-1px)'; }}
      onMouseLeave={(e) => { e.currentTarget.style.boxShadow = 'none'; e.currentTarget.style.transform = 'translateY(0)'; }}
    >
      {/* 上段: ブランドバッジ + タイトル + 状態 */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 12 }}>
        <span style={{
          width: 26, height: 26, borderRadius: 7, flexShrink: 0,
          background: brand ? `${brand.primary}1a` : '#eee',
          color: brand ? brand.primary : '#6b6e7a',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          fontSize: 12, fontWeight: 900,
        }} className="maru">{BRAND_INITIAL[poll.brand] || '？'}</span>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div className="maru" style={{ fontSize: 14, fontWeight: 700, color: '#2c3140', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{poll.title}</div>
          <div style={{ fontSize: 10, color: '#9499a8', fontWeight: 600 }}>{brand ? brand.name : ''} · {poll.createdBy}</div>
        </div>
        {poll.invitedCustomerIds && (
          <span style={{ display: 'flex', alignItems: 'center', gap: 3, fontSize: 10, color: BRAND.closed.primary, fontWeight: 700, background: BRAND.closed.softer, padding: '3px 8px', borderRadius: 999 }}>
            <Lock size={10} /> 招待制
          </span>
        )}
      </div>

      {/* 中段: 候補日数 + 回答進捗 */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 10 }}>
        <span style={{ display: 'flex', alignItems: 'center', gap: 4, fontSize: 11, color: '#6b6e7a', fontWeight: 600 }}>
          <CalendarDays size={12} /> 候補 <span className="num" style={{ color: '#2c3140', fontWeight: 700 }}>{poll.candidateDates.length}</span> 日程
        </span>
        <span style={{ marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 4, fontSize: 11, color: '#6b6e7a', fontWeight: 600 }}>
          <Users size={12} /> 回答 <span className="num" style={{ color: '#2c3140', fontWeight: 700 }}>{responded}/{target}</span> 人
        </span>
      </div>
      <div style={{ height: 7, borderRadius: 999, background: '#f0ede5', overflow: 'hidden', marginBottom: 12 }}>
        <div style={{ height: '100%', width: `${Math.round(ratio * 100)}%`, background: confirmed ? '#4a9968' : (brand ? brand.primary : '#9499a8'), borderRadius: 999, transition: 'width 0.4s' }} />
      </div>

      {/* 下段: 状態 / 期限 or 確定日 */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        {confirmed ? (
          <span className="num" style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: 11, fontWeight: 700, color: '#4a9968' }}>
            <CheckCircle2 size={12} /> {confDate ? `${fmtMD(confDate.date, confDate.day)} で確定` : '確定済み'}
          </span>
        ) : poll.status === 'closed' ? (
          <span style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: 11, fontWeight: 700, color: '#9499a8' }}>
            <XCircle size={12} /> 締め切り済み
          </span>
        ) : (
          <span style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: 11, fontWeight: 600, color: left != null && left <= 2 ? '#d97757' : '#6b6e7a' }}>
            <Clock size={12} /> {deadlineLabel}
          </span>
        )}
        <ChevronRight size={16} color="#cfcbc2" />
      </div>
    </button>
  );
}

function SchedulePollsAdmin({ schedulePolls, pollResponses, addSchedulePoll, updateSchedulePoll, addSession, addParticipant, addAnnounce }) {
  const toast = useToast();
  const [showClosed, setShowClosed] = useState(false);
  const [selected, setSelected] = useState(null);
  const [editing, setEditing] = useState(null); // { mode: 'create' } | { mode: 'edit', poll }

  // 候補日を確定 → 会作成・◯回答者を参加者登録・ポール更新・告知履歴追記
  const confirmPoll = (poll, colIdx, opts = {}) => {
    const cd = poll.candidateDates[colIdx];
    const planKey = poll.plan || opts.planKey || null;
    const planDef = planKey ? PLAN_DEFS[planKey] : null;
    const brandKey = planDef ? planDef.brand : poll.brand;
    const needsCustomPrice = planDef ? planDef.price === null : true;
    const customPrice = needsCustomPrice ? (opts.customPrice != null ? Number(opts.customPrice) : (poll.customPrice ?? null)) : null;

    // 会タイトル：イベント/クローズドのみポール title を customTitle として引き継ぐ。
    // 通常プラン（okiraku/stepup/taimen）は customTitle を空にして plan ラベルを会タイトルにする
    // （「〇〇の日程調整」という調整向けタイトルが通常会の名前に化けるのを防ぐ）
    const carryTitle = brandKey === 'event' || brandKey === 'closed';

    const sessionId = Date.now();
    const newSession = {
      id: sessionId,
      date: cd.date, day: cd.day, time: cd.time,
      plan: planKey,
      gm: 'GM未設定', // 確定後に会の編集画面で設定する運用
      platform: planDef ? (planDef.mode === 'offline' ? '対面' : 'Zoom') : 'Zoom',
      meetingUrl: null,
      guestName: null,
      guestBio: null,
      customTitle: carryTitle ? (poll.title || null) : null,
      customPrice,
      invitedCustomerIds: poll.invitedCustomerIds || [],
      status: 'open',
      fromPollId: poll.id, // 由来をたどれるように
    };
    addSession(newSession);

    // ◯回答者を参加者として自動登録（未払い）
    const yesResponders = pollResponses.filter(r => r.pollId === poll.id && r.answers && r.answers[colIdx] === 'yes');
    const newParticipants = yesResponders.map(r => ({
      id: `p${sessionId}_${r.customerId}`,
      sessionId, customerId: r.customerId,
      name: r.name, handle: r.handle,
      paid: false, paidAt: null,
      cancelled: false, refunded: false, role: null,
    }));
    newParticipants.forEach(p => addParticipant(p));

    // ポールを確定済みに（プラン未定だった場合は確定時に選んだ plan/brand も反映）
    updateSchedulePoll(poll.id, { status: 'confirmed', confirmedIndex: colIdx, plan: planKey, brand: brandKey });

    // 告知センター履歴に自動エントリ
    addAnnounce({
      date: nowISO(), channel: '日程確定', target: poll.title,
      subject: `日程調整「${poll.title}」を確定（${fmtMD(cd.date, cd.day)}開催）`,
      count: newParticipants.length,
    });

    toast.push(`日程を確定し、参加者 ${newParticipants.length} 名を登録しました`, 'success');
  };

  // selected は schedulePolls の最新を参照（将来の確定操作で内容が変わっても追従）
  const selectedPoll = selected ? schedulePolls.find(p => p.id === selected) : null;

  const editModal = editing && (
    <SchedulePollFormModal
      mode={editing.mode}
      initial={editing.mode === 'edit' ? editing.poll : null}
      onSave={(poll) => {
        if (editing.mode === 'edit') {
          updateSchedulePoll(poll.id, poll);
          toast.push('日程調整を更新しました', 'success');
        } else {
          addSchedulePoll(poll);
          toast.push(`「${poll.title}」を作成しました`, 'success');
        }
        setEditing(null);
      }}
      onClose={() => setEditing(null)}
    />
  );

  if (selectedPoll) {
    return (
      <>
        <PollAggregateView poll={selectedPoll} pollResponses={pollResponses} onBack={() => setSelected(null)} onEdit={() => setEditing({ mode: 'edit', poll: selectedPoll })} onConfirm={(colIdx, opts) => confirmPoll(selectedPoll, colIdx, opts)} />
        {editModal}
      </>
    );
  }

  const active = schedulePolls.filter(p => p.status === 'open');
  const closed = schedulePolls.filter(p => p.status !== 'open');

  const handleSelect = (poll) => setSelected(poll.id);

  return (
    <div style={{ animation: 'fadeUp 0.4s' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 16 }}>
        <h2 className="maru" style={{ fontSize: 18, fontWeight: 900, color: '#2c3140' }}>日程調整</h2>
        <span style={{ fontSize: 11, color: '#9499a8', fontWeight: 600 }}>候補日を提示して参加可否を集める</span>
        <button onClick={() => setEditing({ mode: 'create' })} style={{
          marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 6,
          padding: '9px 16px', background: 'linear-gradient(135deg, #6b5dc7, #3fb8d4)',
          border: 'none', color: '#fff', borderRadius: 8, cursor: 'pointer',
          fontFamily: 'inherit', fontSize: 12, fontWeight: 700,
        }}>
          <Plus size={14} /> 新しい日程調整を作成
        </button>
      </div>
      {editModal}

      {/* 調整中 */}
      {active.length > 0 ? (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: 14, marginBottom: 28 }}>
          {active.map(poll => (
            <PollCard key={poll.id} poll={poll} pollResponses={pollResponses} onClick={() => handleSelect(poll)} />
          ))}
        </div>
      ) : (
        <div style={{ padding: '40px 20px', textAlign: 'center', color: '#9499a8', fontSize: 12, background: '#fff', border: '1px dashed #e0ddd6', borderRadius: 14, marginBottom: 28 }}>
          調整中の日程調整はありません
        </div>
      )}

      {/* 確定済み・終了（折りたたみ） */}
      {closed.length > 0 && (
        <div>
          <button onClick={() => setShowClosed(v => !v)} style={{
            display: 'flex', alignItems: 'center', gap: 6, background: 'transparent', border: 'none',
            cursor: 'pointer', fontFamily: 'inherit', fontSize: 12, fontWeight: 700, color: '#6b6e7a', padding: '6px 0',
          }}>
            <ChevronRight size={14} style={{ transform: showClosed ? 'rotate(90deg)' : 'none', transition: 'transform 0.2s' }} />
            確定済み・終了した日程調整（{closed.length}）
          </button>
          {showClosed && (
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: 14, marginTop: 12, opacity: 0.85 }}>
              {closed.map(poll => (
                <PollCard key={poll.id} poll={poll} pollResponses={pollResponses} onClick={() => handleSelect(poll)} />
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// ============ 日程調整（作成/編集モーダル）============
const POLL_DOW = ['日', '月', '火', '水', '木', '金', '土'];
function dowOf(dateStr) {
  if (!dateStr) return '';
  const d = new Date(dateStr);
  return isNaN(d.getTime()) ? '' : POLL_DOW[d.getDay()];
}

function SchedulePollFormModal({ mode, initial, onSave, onClose }) {
  const isEdit = mode === 'edit';
  const customers = useCustomers();

  const [title, setTitle] = useState(initial?.title || '');
  const [planKey, setPlanKey] = useState(initial?.plan || ''); // '' = 未定
  const [candidates, setCandidates] = useState(
    initial?.candidateDates?.length
      ? initial.candidateDates.map(cd => ({ date: cd.date, time: cd.time }))
      : [{ date: '', time: '19:30-22:30' }]
  );
  const [targetMode, setTargetMode] = useState(initial?.invitedCustomerIds ? 'selected' : 'all');
  const [invited, setInvited] = useState(new Set(initial?.invitedCustomerIds || []));
  const [inviteSearch, setInviteSearch] = useState('');
  const [deadline, setDeadline] = useState(initial?.deadline || '');
  const [note, setNote] = useState(initial?.note || '');

  const plan = planKey ? PLAN_DEFS[planKey] : null;
  const brand = plan ? BRAND[plan.brand] : null;
  const accent = brand ? brand.primary : '#6b5dc7';
  // 確定済みポールは候補日の添字が sessions/通知と紐づくため、候補日を変更不可にする（confirmedIndex ズレ防止）
  const lockedCandidates = isEdit && initial?.status === 'confirmed';

  // 候補日の操作
  const addCandidate = () => setCandidates(prev => [...prev, { date: '', time: '19:30-22:30' }]);
  const removeCandidate = (idx) => setCandidates(prev => prev.length > 1 ? prev.filter((_, i) => i !== idx) : prev);
  const updateCandidate = (idx, patch) => setCandidates(prev => prev.map((c, i) => i === idx ? { ...c, ...patch } : c));

  const toggleInvite = (id) => setInvited(prev => {
    const next = new Set(prev);
    next.has(id) ? next.delete(id) : next.add(id);
    return next;
  });
  const filteredCustomers = customers.filter(c => !inviteSearch || c.name.includes(inviteSearch) || c.handle.includes(inviteSearch));

  const validCandidates = candidates.filter(c => c.date);
  const canSave = validCandidates.length >= 1 && (targetMode === 'all' || invited.size >= 1);

  const handleSave = () => {
    const candidateDates = validCandidates.map(c => ({ date: c.date, day: dowOf(c.date), time: c.time || '' }));
    // タイトル未入力なら自動生成
    const firstMonth = candidateDates[0] ? Number(candidateDates[0].date.slice(5, 7)) : null;
    const autoTitle = `${brand ? brand.name + 'の' : ''}日程調整${firstMonth ? `（${firstMonth}月）` : ''}`;
    const poll = {
      id: isEdit ? initial.id : `poll${Date.now()}`,
      title: title.trim() || autoTitle,
      brand: plan ? plan.brand : null,
      plan: planKey || null,
      createdBy: isEdit ? initial.createdBy : '管理者',
      createdAt: isEdit ? initial.createdAt : new Date().toISOString().slice(0, 16).replace('T', ' '),
      candidateDates,
      status: isEdit ? initial.status : 'open',
      confirmedIndex: isEdit ? (initial.confirmedIndex ?? null) : null,
      invitedCustomerIds: targetMode === 'selected' ? Array.from(invited) : null,
      deadline: deadline || null,
      note: note.trim() || '',
    };
    onSave(poll);
  };

  return (
    <ModalShell onClose={onClose} maxWidth={640}>
      <ModalHeader
        title={isEdit ? '日程調整を編集' : '新しい日程調整'}
        subtitle={isEdit ? '候補日や対象を変更できます' : '候補日を提示して参加可否を集めます'}
        icon={<ListChecks size={16} />}
        onClose={onClose}
        accent={accent}
      />

      <div style={{ flex: 1, overflow: 'auto', padding: '20px 24px' }}>
        {/* タイトル */}
        <Field label="タイトル（未入力なら自動生成）">
          <input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="例: 6月 対面会の日程調整" style={inputStyle} />
        </Field>

        {/* 会のタイプ */}
        <div style={{ marginBottom: 18 }}>
          <FieldLabel>会のタイプ</FieldLabel>
          <button onClick={() => setPlanKey('')} style={{
            padding: '8px 14px', marginBottom: 8,
            background: planKey === '' ? '#6b6e7a' : '#fff',
            border: `1.5px solid ${planKey === '' ? '#6b6e7a' : '#e0ddd6'}`,
            color: planKey === '' ? '#fff' : '#6b6e7a',
            borderRadius: 8, cursor: 'pointer', fontFamily: 'inherit', fontSize: 11, fontWeight: 700,
          }}>未定のまま（あとで設定）</button>
          <div style={{ display: 'grid', gap: 6 }}>
            {Object.entries(BRAND).map(([brandKey, b]) => {
              const plansInBrand = Object.entries(PLAN_DEFS).filter(([, pd]) => pd.brand === brandKey);
              return (
                <div key={brandKey}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 6, marginTop: brandKey !== 'okiraku' ? 10 : 0 }}>
                    {b.icon && <img src={b.icon} alt="" style={{ width: 18, height: 18 }} />}
                    <span style={{ fontSize: 11, fontWeight: 700, color: b.primary }}>{b.name}</span>
                  </div>
                  <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(160px, 1fr))', gap: 6 }}>
                    {plansInBrand.map(([k, pd]) => (
                      <button key={k} onClick={() => setPlanKey(k)} style={{
                        padding: '9px 12px', textAlign: 'left',
                        background: planKey === k ? b.primary : '#fff',
                        border: `1.5px solid ${planKey === k ? b.primary : '#e0ddd6'}`,
                        color: planKey === k ? '#fff' : '#2c3140',
                        borderRadius: 8, cursor: 'pointer', fontFamily: 'inherit',
                        fontSize: 11, fontWeight: 600, transition: 'all 0.15s',
                      }}>
                        <div style={{ fontWeight: 700 }}>{pd.label}</div>
                        <div style={{ fontSize: 9, marginTop: 2, opacity: 0.85 }}>
                          {pd.price !== null ? fmtYen(pd.price) : '都度設定'} · {pd.capacity}名{pd.mode === 'offline' && ' · 対面'}
                        </div>
                      </button>
                    ))}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* 候補日リスト */}
        <div style={{ marginBottom: 18 }}>
          <FieldLabel>候補日（最低1つ）</FieldLabel>
          {lockedCandidates && (
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, padding: '9px 12px', marginBottom: 10, background: '#e6f3eb', border: '1px solid #b8d9c4', borderRadius: 8, fontSize: 11, color: '#3a8c5b', fontWeight: 600 }}>
              <Lock size={12} /> 確定済みのため候補日は変更できません
            </div>
          )}
          <div style={{ display: 'grid', gap: 8 }}>
            {candidates.map((c, idx) => (
              <div key={idx} style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
                <input type="date" value={c.date} onChange={(e) => updateCandidate(idx, { date: e.target.value })} readOnly={lockedCandidates} style={{ ...inputStyle, flex: '1.3', ...(lockedCandidates && { background: '#fafaf6', color: '#9499a8' }) }} />
                <span className="num" style={{ fontSize: 12, color: '#9499a8', width: 24, textAlign: 'center', flexShrink: 0 }}>{c.date ? `（${dowOf(c.date)}）` : ''}</span>
                <input value={c.time} onChange={(e) => updateCandidate(idx, { time: e.target.value })} readOnly={lockedCandidates} placeholder="19:30-22:30" style={{ ...inputStyle, flex: '1', ...(lockedCandidates && { background: '#fafaf6', color: '#9499a8' }) }} />
                <button onClick={() => removeCandidate(idx)} disabled={lockedCandidates || candidates.length <= 1} style={{
                  flexShrink: 0, width: 34, height: 34, display: 'flex', alignItems: 'center', justifyContent: 'center',
                  background: '#fff', border: '1px solid #e0ddd6', borderRadius: 8,
                  cursor: (lockedCandidates || candidates.length <= 1) ? 'not-allowed' : 'pointer',
                  color: (lockedCandidates || candidates.length <= 1) ? '#d4d0c8' : '#d44a4a',
                }} title="この候補日を削除"><X size={15} /></button>
              </div>
            ))}
          </div>
          {!lockedCandidates && (
            <button onClick={addCandidate} style={{
              marginTop: 8, display: 'flex', alignItems: 'center', gap: 5, padding: '8px 14px',
              background: '#fff', border: '1px dashed #c9c4ba', color: '#6b6e7a',
              borderRadius: 8, cursor: 'pointer', fontFamily: 'inherit', fontSize: 11, fontWeight: 700,
            }}><Plus size={13} /> 候補日を追加</button>
          )}
        </div>

        {/* 依頼対象 */}
        <div style={{ marginBottom: 18 }}>
          <FieldLabel>依頼対象</FieldLabel>
          <div style={{ display: 'flex', gap: 8, marginBottom: 10 }}>
            {[{ k: 'all', label: '全顧客' }, { k: 'selected', label: '選んだ人' }].map(opt => (
              <button key={opt.k} onClick={() => setTargetMode(opt.k)} style={{
                flex: 1, padding: '10px', borderRadius: 8, cursor: 'pointer', fontFamily: 'inherit', fontSize: 12, fontWeight: 700,
                background: targetMode === opt.k ? accent : '#fff',
                border: `1.5px solid ${targetMode === opt.k ? accent : '#e0ddd6'}`,
                color: targetMode === opt.k ? '#fff' : '#6b6e7a',
              }}>{opt.label}</button>
            ))}
          </div>
          {targetMode === 'selected' && (
            <div style={{ border: '1px solid #e8e5dd', borderRadius: 10, overflow: 'hidden' }}>
              <div style={{ padding: '10px 12px', borderBottom: '1px solid #f0ede5', display: 'flex', gap: 10, alignItems: 'center' }}>
                <div style={{ position: 'relative', flex: 1 }}>
                  <Search size={13} color="#9499a8" style={{ position: 'absolute', left: 11, top: 9 }} />
                  <input value={inviteSearch} onChange={(e) => setInviteSearch(e.target.value)} placeholder="顧客を検索" style={{ ...inputStyle, fontSize: 12, padding: '8px 12px 8px 32px' }} />
                </div>
                <span className="num" style={{ fontSize: 12, color: accent, fontWeight: 700, whiteSpace: 'nowrap' }}>{invited.size} 名選択中</span>
              </div>
              <div style={{ maxHeight: 220, overflow: 'auto' }}>
                {filteredCustomers.map(c => {
                  const checked = invited.has(c.id);
                  return (
                    <div key={c.id} onClick={() => toggleInvite(c.id)} style={{
                      padding: '9px 12px', display: 'flex', alignItems: 'center', gap: 10,
                      cursor: 'pointer', background: checked ? `${accent}12` : 'transparent', transition: 'background 0.15s',
                    }}>
                      <div style={{
                        width: 18, height: 18, borderRadius: 5, flexShrink: 0,
                        border: `2px solid ${checked ? accent : '#d4d0c8'}`, background: checked ? accent : '#fff',
                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                      }}>{checked && <Check size={12} color="#fff" strokeWidth={3} />}</div>
                      <span style={{ width: 30, height: 30, borderRadius: '50%', flexShrink: 0, background: '#e0ddd6', color: '#6b6e7a', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 12, fontWeight: 700 }}>{c.avatar}</span>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{ fontSize: 12, color: '#2c3140', fontWeight: 600 }}>{c.name}</div>
                        <div className="num" style={{ fontSize: 10, color: '#9499a8' }}>{c.handle} · {c.tier} · 参加{c.total}回</div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </div>

        {/* 推奨期限 */}
        <Field label="推奨期限（任意）">
          <input type="date" value={deadline} onChange={(e) => setDeadline(e.target.value)} style={inputStyle} />
        </Field>

        {/* メモ */}
        <Field label="メモ（任意）">
          <textarea value={note} onChange={(e) => setNote(e.target.value)} rows={2} placeholder="例: 会場の都合で土日のみ。6人以上集まった日で開催します。" style={{ ...inputStyle, resize: 'vertical' }} />
        </Field>
      </div>

      <div style={{ padding: 16, borderTop: '1px solid #f0ede5', display: 'flex', gap: 8 }}>
        <button onClick={onClose} style={{
          flex: 1, padding: 11, background: '#fff', border: '1px solid #d4d0c8',
          color: '#2c3140', borderRadius: 8, cursor: 'pointer', fontFamily: 'inherit', fontSize: 12, fontWeight: 600,
        }}>キャンセル</button>
        <button onClick={handleSave} disabled={!canSave} style={{
          flex: 2, padding: 11,
          background: canSave ? `linear-gradient(135deg, ${accent}, ${brand ? brand.accent : '#3fb8d4'})` : '#e0ddd6',
          border: 'none', color: '#fff', borderRadius: 8,
          cursor: canSave ? 'pointer' : 'not-allowed',
          fontFamily: 'inherit', fontSize: 12, fontWeight: 700,
          display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6,
        }}>
          <Check size={13} /> {isEdit ? '変更を保存' : 'この内容で作成'}
        </button>
      </div>
    </ModalShell>
  );
}

// ============ 日程調整（集計表）============
// 回答区分のカラー（ROLE_STYLES と同系の落ち着いた配色を流用）
const ANSWER_STYLE = {
  yes:   { mark: '◯', color: '#4a9968', bg: '#e6f3eb', label: '参加可' },
  maybe: { mark: '△', color: '#c9962a', bg: '#fdf3d8', label: '調整可' },
  no:    { mark: '×', color: '#d44a4a', bg: '#fde8e8', label: '不可' },
  none:  { mark: '─', color: '#b0ada5', bg: '#f5f3ee', label: '未回答' },
};

function PollAggregateView({ poll, pollResponses, onBack, onEdit, onConfirm }) {
  const customers = useCustomers();
  const [confirmingIndex, setConfirmingIndex] = useState(null);
  const brand = BRAND[poll.brand];
  const accent = brand ? brand.primary : '#2c3140';
  const HILITE = '#eef7f1'; // 最有力候補の薄い緑

  // 対象顧客（公開=全顧客 / 招待制=招待された顧客）
  const targets = poll.invitedCustomerIds
    ? customers.filter(c => poll.invitedCustomerIds.includes(c.id))
    : customers;

  // customerId -> 回答
  const resByCustomer = {};
  pollResponses.filter(r => r.pollId === poll.id).forEach(r => { resByCustomer[r.customerId] = r; });
  // answers のキーは candidateDates の添字（0,1,2...）
  const answerOf = (customerId, colIdx) => {
    const r = resByCustomer[customerId];
    if (!r || !r.answers) return 'none';
    return r.answers[colIdx] || 'none';
  };

  // 列ごとの集計
  const colStats = poll.candidateDates.map((_, colIdx) => {
    const s = { yes: 0, maybe: 0, no: 0, none: 0 };
    targets.forEach(c => { s[answerOf(c.id, colIdx)]++; });
    return s;
  });
  const maxYes = Math.max(0, ...colStats.map(s => s.yes));
  const isTop = (colIdx) => maxYes > 0 && colStats[colIdx].yes === maxYes;

  const respondedCount = targets.filter(c => resByCustomer[c.id]).length;
  const confirmedDate = poll.status === 'confirmed' && poll.confirmedIndex != null ? poll.candidateDates[poll.confirmedIndex] : null;

  const alreadyConfirmed = poll.status === 'confirmed';

  const th = { padding: '10px 12px', borderBottom: '2px solid #e8e5dd', fontSize: 11, fontWeight: 700, color: '#6b6e7a', whiteSpace: 'nowrap' };
  const td = { padding: '9px 12px', borderBottom: '1px solid #f0ede5', textAlign: 'center', fontSize: 13 };

  return (
    <div style={{ animation: 'fadeUp 0.4s' }}>
      <BackButton onClick={onBack} label="日程調整一覧へ戻る" accent={accent} />

      {/* サマリ */}
      <div style={{ background: '#fff', border: '1px solid #e8e5dd', borderRadius: 14, padding: 20, marginTop: 14, marginBottom: 18 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 10 }}>
          <span className="maru" style={{
            width: 30, height: 30, borderRadius: 8, flexShrink: 0,
            background: brand ? `${brand.primary}1a` : '#eee', color: accent,
            display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 14, fontWeight: 900,
          }}>{BRAND_INITIAL[poll.brand] || '？'}</span>
          <div>
            <h2 className="maru" style={{ fontSize: 18, fontWeight: 900, color: '#2c3140' }}>{poll.title}</h2>
            <div style={{ fontSize: 11, color: '#9499a8', fontWeight: 600 }}>{brand ? brand.name : ''} · {poll.createdBy}</div>
          </div>
          <div style={{ marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 8 }}>
            {poll.invitedCustomerIds && (
              <span style={{ display: 'flex', alignItems: 'center', gap: 3, fontSize: 10, color: BRAND.closed.primary, fontWeight: 700, background: BRAND.closed.softer, padding: '4px 10px', borderRadius: 999 }}>
                <Lock size={10} /> 招待制
              </span>
            )}
            {onEdit && (
              <button onClick={onEdit} style={{
                display: 'flex', alignItems: 'center', gap: 5, padding: '6px 12px',
                background: '#fff', border: `1.5px solid ${accent}`, color: accent,
                borderRadius: 8, cursor: 'pointer', fontFamily: 'inherit', fontSize: 11, fontWeight: 700,
              }}>編集</button>
            )}
          </div>
        </div>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 18, fontSize: 12, color: '#6b6e7a', fontWeight: 600 }}>
          <span style={{ display: 'flex', alignItems: 'center', gap: 5 }}><CalendarDays size={13} /> 候補 <span className="num" style={{ color: '#2c3140', fontWeight: 700 }}>{poll.candidateDates.length}</span> 日程</span>
          <span style={{ display: 'flex', alignItems: 'center', gap: 5 }}><Users size={13} /> 回答 <span className="num" style={{ color: '#2c3140', fontWeight: 700 }}>{respondedCount}/{targets.length}</span> 人</span>
          {confirmedDate
            ? <span className="num" style={{ display: 'flex', alignItems: 'center', gap: 5, color: '#4a9968', fontWeight: 700 }}><CheckCircle2 size={13} /> {fmtMD(confirmedDate.date, confirmedDate.day)} で確定</span>
            : <span style={{ display: 'flex', alignItems: 'center', gap: 5 }}><Clock size={13} /> 推奨期限 <span className="num" style={{ color: '#2c3140', fontWeight: 700 }}>{poll.deadline}</span></span>}
        </div>
        {poll.note && <div style={{ marginTop: 10, fontSize: 11, color: '#9499a8' }}>{poll.note}</div>}
        {/* 凡例 */}
        <div style={{ display: 'flex', gap: 14, marginTop: 12, paddingTop: 12, borderTop: '1px dashed #e0ddd6' }}>
          {['yes', 'maybe', 'no', 'none'].map(k => (
            <span key={k} style={{ display: 'flex', alignItems: 'center', gap: 4, fontSize: 11, color: '#6b6e7a', fontWeight: 600 }}>
              <span style={{ color: ANSWER_STYLE[k].color, fontWeight: 900 }}>{ANSWER_STYLE[k].mark}</span> {ANSWER_STYLE[k].label}
            </span>
          ))}
        </div>
      </div>

      {/* 集計マトリクス */}
      <div style={{ background: '#fff', border: '1px solid #e8e5dd', borderRadius: 14, overflowX: 'auto' }}>
        <table style={{ borderCollapse: 'collapse', width: '100%', minWidth: 480 }}>
          <thead>
            <tr>
              <th style={{ ...th, textAlign: 'left', position: 'sticky', left: 0, background: '#fff', zIndex: 1 }}>参加者</th>
              {poll.candidateDates.map((cd, i) => (
                <th key={i} style={{ ...th, textAlign: 'center', background: isTop(i) ? HILITE : '#fff' }}>
                  <div className="maru" style={{ fontSize: 13, fontWeight: 700, color: '#2c3140' }}>{fmtMD(cd.date, cd.day)}</div>
                  <div className="num" style={{ fontSize: 10, color: '#9499a8', marginTop: 2 }}>{cd.time}</div>
                  {isTop(i) && <div style={{ fontSize: 9, color: '#4a9968', fontWeight: 700, marginTop: 2 }}>★ 最有力</div>}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {targets.map(c => {
              const answered = !!resByCustomer[c.id];
              return (
                <tr key={c.id}>
                  <td style={{ ...td, textAlign: 'left', position: 'sticky', left: 0, background: '#fff', zIndex: 1 }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                      <span style={{ width: 24, height: 24, borderRadius: '50%', flexShrink: 0, background: answered ? `${accent}1a` : '#f0ede5', color: answered ? accent : '#b0ada5', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 11, fontWeight: 700 }}>{c.avatar}</span>
                      <div style={{ minWidth: 0 }}>
                        <div style={{ fontSize: 12, fontWeight: 600, color: answered ? '#2c3140' : '#9499a8', whiteSpace: 'nowrap' }}>{c.name}</div>
                        <div className="num" style={{ fontSize: 9, color: '#b0ada5', whiteSpace: 'nowrap' }}>{c.handle}</div>
                      </div>
                    </div>
                  </td>
                  {poll.candidateDates.map((_, colIdx) => {
                    const a = answerOf(c.id, colIdx);
                    const st = ANSWER_STYLE[a];
                    return (
                      <td key={colIdx} style={{ ...td, background: isTop(colIdx) ? HILITE : 'transparent' }}>
                        <span style={{ display: 'inline-flex', alignItems: 'center', justifyContent: 'center', width: 26, height: 26, borderRadius: 7, background: st.bg, color: st.color, fontWeight: 900, fontSize: 14 }}>{st.mark}</span>
                      </td>
                    );
                  })}
                </tr>
              );
            })}
          </tbody>
          <tfoot>
            {[
              { key: 'yes',   label: '◯ 合計' },
              { key: 'maybe', label: '△ 合計' },
              { key: 'no',    label: '× 合計' },
              { key: 'none',  label: '未回答' },
            ].map((row, ri) => (
              <tr key={row.key}>
                <td style={{ ...td, textAlign: 'left', fontWeight: 700, fontSize: 11, color: ANSWER_STYLE[row.key].color, position: 'sticky', left: 0, background: '#faf9f6', borderTop: ri === 0 ? '2px solid #e8e5dd' : 'none' }}>{row.label}</td>
                {colStats.map((s, colIdx) => (
                  <td key={colIdx} className="num" style={{ ...td, fontWeight: 700, color: ANSWER_STYLE[row.key].color, background: isTop(colIdx) ? HILITE : '#faf9f6', borderTop: ri === 0 ? '2px solid #e8e5dd' : 'none' }}>{s[row.key]}</td>
                ))}
              </tr>
            ))}
            {/* 確定ボタン行 */}
            <tr>
              <td style={{ ...td, background: '#faf9f6', position: 'sticky', left: 0, borderBottom: 'none' }}></td>
              {poll.candidateDates.map((cd, colIdx) => {
                const isConfirmed = poll.confirmedIndex === colIdx;
                const disabled = alreadyConfirmed; // 確定後は他候補での確定も不可
                return (
                  <td key={colIdx} style={{ ...td, background: isTop(colIdx) ? HILITE : '#faf9f6', borderBottom: 'none', padding: '12px' }}>
                    <button onClick={() => !disabled && setConfirmingIndex(colIdx)} disabled={disabled} style={{
                      padding: '7px 10px', width: '100%',
                      background: isConfirmed ? '#e6f3eb' : (disabled ? '#eceae4' : accent),
                      color: isConfirmed ? '#4a9968' : (disabled ? '#b0ada5' : '#fff'),
                      border: 'none', borderRadius: 8, fontSize: 11, fontWeight: 700,
                      fontFamily: 'inherit', cursor: disabled ? 'default' : 'pointer', whiteSpace: 'nowrap',
                    }}>{isConfirmed ? '確定済み' : 'この日で確定'}</button>
                  </td>
                );
              })}
            </tr>
          </tfoot>
        </table>
      </div>

      {confirmingIndex != null && (
        <PollConfirmModal
          poll={poll}
          colIdx={confirmingIndex}
          pollResponses={pollResponses}
          onConfirm={(opts) => { onConfirm?.(confirmingIndex, opts); setConfirmingIndex(null); }}
          onClose={() => setConfirmingIndex(null)}
        />
      )}
    </div>
  );
}

// ============ 日程調整（確定ダイアログ）============
function PollConfirmModal({ poll, colIdx, pollResponses, onConfirm, onClose }) {
  const cd = poll.candidateDates[colIdx];
  // プラン未定なら確定時にプラン選択必須
  const [planKey, setPlanKey] = useState(poll.plan || '');
  const plan = planKey ? PLAN_DEFS[planKey] : null;
  const brand = plan ? BRAND[plan.brand] : null;
  const accent = brand ? brand.primary : '#6b5dc7';
  const needsPlan = !poll.plan; // 元々未定だった場合のみ選択UIを出す
  const needsPrice = plan ? plan.price === null : false;
  const [customPrice, setCustomPrice] = useState(poll.customPrice ?? '');

  // この候補日に対する回答内訳
  const responses = pollResponses.filter(r => r.pollId === poll.id);
  const countBy = (val) => responses.filter(r => r.answers && r.answers[colIdx] === val).length;
  const yesN = countBy('yes'), maybeN = countBy('maybe'), noN = countBy('no');

  const planLabel = plan ? plan.label : poll.title;
  const canConfirm = (!needsPlan || planKey) && (!needsPrice || customPrice !== '');

  const handleConfirm = () => {
    if (!canConfirm) return;
    onConfirm({ planKey: planKey || null, customPrice: needsPrice ? customPrice : undefined });
  };

  const checkLine = (color, text) => (
    <div style={{ display: 'flex', alignItems: 'flex-start', gap: 8, fontSize: 12, color: '#2c3140', lineHeight: 1.6 }}>
      <Check size={14} color={color} strokeWidth={3} style={{ marginTop: 2, flexShrink: 0 }} /> <span>{text}</span>
    </div>
  );

  return (
    <ModalShell onClose={onClose} maxWidth={440}>
      <ModalHeader title="日程を確定" icon={<CheckCircle2 size={16} />} onClose={onClose} accent={accent} />
      <div style={{ flex: 1, overflow: 'auto', padding: '18px 24px' }}>
        <div style={{ fontSize: 13, color: '#2c3140', fontWeight: 600, lineHeight: 1.7, marginBottom: 16 }}>
          「<span className="num" style={{ color: accent, fontWeight: 700 }}>{fmtMD(cd.date, cd.day)} {cd.time}</span>」で確定し、<br />
          <span style={{ fontWeight: 700 }}>{planLabel}</span> として正式な会を作成します。
        </div>

        {/* プラン選択（未定だった場合のみ・必須） */}
        {needsPlan && (
          <div style={{ marginBottom: 16, padding: 12, background: '#faf9f6', borderRadius: 10, border: '1px solid #e8e5dd' }}>
            <FieldLabel>会のタイプを選択（必須）</FieldLabel>
            <select value={planKey} onChange={(e) => setPlanKey(e.target.value)} style={{ ...inputStyle, cursor: 'pointer' }}>
              <option value="">選択してください</option>
              {Object.entries(BRAND).map(([brandKey, b]) => (
                <optgroup key={brandKey} label={b.name}>
                  {Object.entries(PLAN_DEFS).filter(([, pd]) => pd.brand === brandKey).map(([k, pd]) => (
                    <option key={k} value={k}>{pd.label}（{pd.price !== null ? fmtYen(pd.price) : '都度設定'}）</option>
                  ))}
                </optgroup>
              ))}
            </select>
          </div>
        )}

        {/* 参加費（プランが都度設定の場合・必須） */}
        {needsPrice && (
          <div style={{ marginBottom: 16 }}>
            <FieldLabel>参加費（必須）</FieldLabel>
            <input type="number" value={customPrice} onChange={(e) => setCustomPrice(e.target.value)} placeholder="例: 4000" style={inputStyle} />
          </div>
        )}

        <div style={{ display: 'grid', gap: 9, padding: '14px 16px', background: '#f6f8f6', borderRadius: 10, border: '1px solid #e0e8e0' }}>
          {checkLine('#4a9968', <>◯回答した <b className="num">{yesN}</b> 名を参加者として自動登録</>)}
          {checkLine('#c9962a', <>△回答した <b className="num">{maybeN}</b> 名には参加確認の通知を送る</>)}
          {checkLine('#d44a4a', <>×回答した <b className="num">{noN}</b> 名には確定日のみ通知</>)}
        </div>
      </div>

      <div style={{ padding: 16, borderTop: '1px solid #f0ede5', display: 'flex', gap: 8 }}>
        <button onClick={onClose} style={{
          flex: 1, padding: 11, background: '#fff', border: '1px solid #d4d0c8',
          color: '#2c3140', borderRadius: 8, cursor: 'pointer', fontFamily: 'inherit', fontSize: 12, fontWeight: 600,
        }}>キャンセル</button>
        <button onClick={handleConfirm} disabled={!canConfirm} style={{
          flex: 2, padding: 11,
          background: canConfirm ? `linear-gradient(135deg, ${accent}, ${brand ? brand.accent : '#3fb8d4'})` : '#e0ddd6',
          border: 'none', color: '#fff', borderRadius: 8,
          cursor: canConfirm ? 'pointer' : 'not-allowed',
          fontFamily: 'inherit', fontSize: 12, fontWeight: 700,
          display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6,
        }}>
          <Check size={13} /> この内容で確定
        </button>
      </div>
    </ModalShell>
  );
}

// ============ ダッシュボード ============
function Dashboard({ sessions, participants }) {
  const upcoming = sessions.filter(s => s.status === 'open').map(enrichSession);
  const totalRevenue = upcoming.reduce((sum, s) => {
    const cnt = participants.filter(p => p.sessionId === s.id && !p.cancelled).length;
    return sum + s.price * cnt;
  }, 0);
  const totalBookings = participants.filter(p => upcoming.some(s => s.id === p.sessionId) && !p.cancelled).length;
  const unpaid = participants.filter(p => upcoming.some(s => s.id === p.sessionId) && !p.cancelled && !p.paid).length;
  const refundsDue = participants.filter(p => p.cancelled && !p.refunded && p.paid).length;

  // ブランド別売上
  const byBrand = {};
  upcoming.forEach(s => {
    const cnt = participants.filter(p => p.sessionId === s.id && !p.cancelled).length;
    byBrand[s.brand.key] = (byBrand[s.brand.key] || 0) + s.price * cnt;
  });

  return (
    <div className="fadeup">
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 12, marginBottom: 28 }}>
        <KPI label="今月の売上見込" value={fmtYen(totalRevenue)} accent="#5b9bd5" />
        <KPI label="予約総数" value={`${totalBookings}件`} accent="#6b5dc7" />
        <KPI label="未払い件数" value={`${unpaid}件`} accent="#e8645f" />
        <KPI label="返金処理待ち" value={`${refundsDue}件`} accent="#d44a4a" />
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1.6fr 1fr', gap: 16 }}>
        <section style={{ padding: 20, background: '#fff', border: '1px solid #e8e5dd', borderRadius: 12 }}>
          <h3 className="maru" style={{ fontSize: 14, fontWeight: 900, color: '#2c3140', margin: '0 0 16px' }}>開催予定の会</h3>
          {upcoming.slice(0, 6).map(s => {
            const cnt = participants.filter(p => p.sessionId === s.id && !p.cancelled).length;
            const ratio = cnt / s.capacity;
            return (
              <div key={s.id} style={{
                padding: '11px 0', display: 'grid',
                gridTemplateColumns: '90px 100px 1fr 90px 70px', gap: 12, alignItems: 'center',
                borderBottom: '1px solid #f5f3ed',
              }}>
                <div className="num" style={{ fontSize: 12, color: '#2c3140', fontWeight: 600 }}>{fmtMD(s.date, s.day)}</div>
                <span style={{ padding: '2px 8px', fontSize: 9, fontWeight: 700, borderRadius: 999, background: `${s.brand.primary}1a`, color: s.brand.primary, justifySelf: 'start' }}>
                  {s.brand.name.replace('人狼会', '')}{s.isOffline && '・対面'}
                </span>
                <div>
                  <div style={{ height: 4, background: '#f0ede5', borderRadius: 2, overflow: 'hidden' }}>
                    <div style={{ width: `${ratio * 100}%`, height: '100%', background: s.brand.primary, transition: 'width 0.5s' }} />
                  </div>
                  <div className="num" style={{ fontSize: 10, color: '#9499a8', marginTop: 3 }}>{cnt} / {s.capacity} · {s.title}</div>
                </div>
                <div className="num" style={{ fontSize: 12, color: s.brand.primary, fontWeight: 700, textAlign: 'right' }}>{fmtYen(s.price * cnt)}</div>
                <div style={{ fontSize: 9, fontWeight: 700, textAlign: 'right',
                  color: ratio === 1 ? '#d44a4a' : ratio > 0.7 ? '#e8645f' : '#9499a8' }}>
                  ● {ratio === 1 ? '満員' : ratio > 0.7 ? '残僅か' : '受付中'}
                </div>
              </div>
            );
          })}
        </section>

        <section style={{ padding: 20, background: '#fff', border: '1px solid #e8e5dd', borderRadius: 12 }}>
          <h3 className="maru" style={{ fontSize: 14, fontWeight: 900, color: '#2c3140', margin: '0 0 16px' }}>ブランド別売上</h3>
          {Object.entries(BRAND).filter(([k]) => byBrand[k]).map(([k, b]) => {
            const sum = byBrand[k] || 0;
            const ratio = totalRevenue ? sum / totalRevenue : 0;
            return (
              <div key={k} style={{ marginBottom: 14 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 5 }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                    {b.icon && <img src={b.icon} alt="" style={{ width: 18, height: 18 }} />}
                    <span style={{ fontSize: 12, color: '#2c3140', fontWeight: 600 }}>{b.name}</span>
                  </div>
                  <span className="num" style={{ fontSize: 12, color: b.primary, fontWeight: 700 }}>{fmtYen(sum)}</span>
                </div>
                <div style={{ height: 6, background: '#f0ede5', borderRadius: 3, overflow: 'hidden' }}>
                  <div style={{ width: `${ratio * 100}%`, height: '100%', background: `linear-gradient(90deg, ${b.primary}, ${b.accent})` }} />
                </div>
              </div>
            );
          })}

          <div style={{ marginTop: 18, padding: 12, background: '#fef7e8', border: '1px solid #f5d97a', borderRadius: 8 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: 10, color: '#c9962a', fontWeight: 700, marginBottom: 5 }}>
              <AlertCircle size={11} /> ALERT
            </div>
            <div style={{ fontSize: 11, color: '#6b6e7a', lineHeight: 1.6 }}>
              5/12 高橋由美様の誕生日。<br />
              5/15 お気楽10人村は残9席、告知のタイミングです。
            </div>
          </div>
        </section>
      </div>
    </div>
  );
}

function KPI({ label, value, accent }) {
  return (
    <div style={{
      padding: '18px 18px 16px', background: '#fff',
      border: '1px solid #e8e5dd', borderRadius: 12,
      position: 'relative', overflow: 'hidden',
    }}>
      <div style={{ position: 'absolute', top: 0, left: 0, width: 4, height: '100%', background: accent }} />
      <div style={{ fontSize: 10, fontWeight: 700, color: '#9499a8', letterSpacing: '0.15em', marginBottom: 8 }}>{label}</div>
      <div className="num" style={{ fontSize: 22, fontWeight: 700, color: '#2c3140' }}>{value}</div>
    </div>
  );
}

